def sliding_window(items, size):
    lst = list(items)
    for i in range(len(lst) - size + 1):
        yield lst[i:i + size]


def pairwise(items):
    lst = list(items)
    for i in range(len(lst) - 1):
        yield (lst[i], lst[i + 1])


def take_while(predicate, items):
    for item in items:
        if not predicate(item):
            return
        yield item
